  async function getAudioRecord(id) {
    return db().get(STORES.AUDIO_RECORD, id);
  }
  async function listAudioRecords(filter = {}) {
    let all = await db().getAll(STORES.AUDIO_RECORD);
    if (filter.lessonId) all = all.filter((r) => r.lessonId === filter.lessonId);
    if (filter.segmentId) all = all.filter((r) => r.segmentId === filter.segmentId);
    return all;
  }
  var BACKUP_CONFIG_ID = "config";
  async function getBackupConfig() {
    const cur = await db().get(STORES.SYSTEM_BACKUP, BACKUP_CONFIG_ID);
    return cur || { id: BACKUP_CONFIG_ID, autoBackup: false, lastBackupAt: null, lastRestoreAt: null };
  }
  async function saveBackupConfig(patch) {
    const cur = await getBackupConfig();
    const next = { ...cur, ...patch, id: BACKUP_CONFIG_ID };
    await db().put(STORES.SYSTEM_BACKUP, next);
    return next;
  }
  var STORE_NAMES = Object.values(STORES);
  async function exportAll() {
    const stores = {};
    for (const name of STORE_NAMES) {
      stores[name] = await db().getAll(name);
    }
    return {
      app: "feynman-chinese-v1",
      version: 1,
      exportedAt: Date.now(),
      stores
    };
  }
  function validateBackup(data) {
    if (!data || typeof data !== "object") return false;
    if (data.app !== "feynman-chinese-v1") return false;
    if (!data.stores || typeof data.stores !== "object") return false;
    return STORE_NAMES.every((name) => Array.isArray(data.stores[name]));
  }
  async function importAll(data, { clearFirst = true } = {}) {
    if (!validateBackup(data)) throw new Error("\u5907\u4EFD\u6587\u4EF6\u683C\u5F0F\u4E0D\u5408\u6CD5");
    for (const name of STORE_NAMES) {
      if (clearFirst) await db().clear(name);
      for (const record of data.stores[name]) {
        await db().put(name, record);
      }
    }
    await saveBackupConfig({ lastRestoreAt: Date.now() });
    return true;
  }
  async function resetAllData() {
    await db().clearAll();
    _resetDatabaseSingleton();
    await saveBackupConfig({ lastBackupAt: null, lastRestoreAt: null });
  }
  var wgId = (lessonId) => `wordgate:${lessonId}`;
