  function hashSeed(str) {
    let h = 0;
    for (let i = 0; i < str.length; i++) {
      h = h * 31 + str.charCodeAt(i) >>> 0;
    }
    return h;
  }
  function generateExerciseSet(weakPoint, count = 3) {
    const tpls = TEMPLATES[weakPoint.category];
    const kp = weakPoint.knowledgePoint || weakPoint.questionText || "\u8BE5\u77E5\u8BC6\u70B9";
    const seed = hashSeed(weakPoint.id || kp);
    const out = [];
    for (let i = 0; i < count; i++) {
      const tpl = tpls[(seed + i) % tpls.length];
      out.push({
        category: weakPoint.category,
        weakPointId: weakPoint.id,
        index: i + 1,
        questionText: tpl.q.replace(/\{kp\}/g, kp),
        referenceAnswer: tpl.a
      });
    }
    return out;
  }

  // src/core/nav.js
  function canAccess(tb, progressMap, route) {
    const type = route.type;
    if (type === "unit" || type === "home" || type === "parent") {
      if (type === "unit") {
        if (!isUnitUnlocked(tb, progressMap, route.unitId)) {
          return { ok: false, reason: `\u8BF7\u5148\u5B8C\u6210\u4E0A\u4E00\u5355\u5143\uFF08${route.unitId} \u5C1A\u672A\u89E3\u9501\uFF09` };
        }
      }
      return { ok: true };
    }
    if (type === "lesson") {
      if (!isUnitUnlocked(tb, progressMap, route.unitId)) {
        return { ok: false, reason: "\u8BE5\u5355\u5143\u5C1A\u672A\u89E3\u9501" };
      }
      if (!isLessonUnlocked(tb, progressMap, route.unitId, route.lessonId)) {
        return { ok: false, reason: "\u8BF7\u5148\u5B8C\u6210\u4E0A\u4E00\u7BC7\u8BFE\u6587" };
      }
      return { ok: true };
    }
    if (type === "segment" || type === "review") {
      if (!isUnitUnlocked(tb, progressMap, route.unitId)) {
        return { ok: false, reason: "\u8BE5\u5355\u5143\u5C1A\u672A\u89E3\u9501" };
      }
      if (!isLessonUnlocked(tb, progressMap, route.unitId, route.lessonId)) {
        return { ok: false, reason: "\u8BF7\u5148\u5B8C\u6210\u4E0A\u4E00\u7BC7\u8BFE\u6587" };
      }
      if (type === "segment" && route.segmentId) {
        if (!isSegmentUnlocked(tb, progressMap, route.lessonId, route.segmentId)) {
          return { ok: false, reason: "\u8BF7\u5148\u5B8C\u6210\u4E0A\u4E00\u6BB5\u843D" };
        }
      }
      return { ok: true };
    }
    return { ok: true };
  }

