    return isBasic(mode) ? ["\u5B57\u8BCD", "\u8BFE\u6587\u7406\u89E3", "\u5199\u4F5C\u65B9\u6CD5"] : ["\u8BFE\u6587\u7406\u89E3", "\u5B57\u8BCD", "\u5199\u4F5C\u65B9\u6CD5"];
