  function buildOptions(correct, pool, seed) {
    const distractors = pool.filter((m) => m && m !== correct);
    const picked = [];
    for (const d of distractors) {
      if (picked.length >= 3) break;
      picked.push(d);
    }
    let g = 0;
    while (picked.length < 3) picked.push(`\uFF08\u5E72\u6270\u9879${++g}\uFF09`);
    const options = picked.slice(0, 3);
    const pos = (seed % 4 + 4) % 4;
    options.splice(pos, 0, correct);
    return { options, answer: pos };
  }
  function buildWordQuiz(lesson) {
    const items = [];
    const meaningPool = [
      ...(lesson.newWords || []).map((w) => w.meaning),
      ...(lesson.words || []).map((w) => w.meaning),
      ...(lesson.fourCharWords || []).map((w) => w.meaning),
      ...GENERIC_MEANINGS
    ];
    (lesson.newWords || []).forEach((w, i) => {
      const { options, answer } = buildOptions(w.meaning, meaningPool, i);
      items.push({
        id: `cw_${lesson.id}_${i}`,
        kind: "charMeaning",
        category: w.require === "\u4F1A\u5199" ? "write" : "recognize",
        prompt: `\u8BF7\u9009\u51FA\u300C${w.char}\u300D\u7684\u6B63\u786E\u91CA\u4E49`,
        options,
        answer,
        explain: `\u300C${w.char}\u300D\u8BFB ${w.pinyin}\uFF0C\u610F\u601D\u662F\uFF1A${w.meaning}`
      });
    });
    (lesson.polyphones || []).forEach((p, pi) => {
      const readings = p.readings || [];
      readings.forEach((rd, ri) => {
        const example = rd.words && rd.words[0] ? rd.words[0] : "";
        const options = readings.map((r) => r.pinyin);
        items.push({
          id: `pp_${lesson.id}_${pi}_${ri}`,
          kind: "polyReading",
          category: "poly",
          prompt: `\u300C${p.char}\u300D\u5728\u300C${example}\u300D\u4E2D\u8BFB\u4EC0\u4E48\u97F3\uFF1F`,
          options,
          answer: ri,
          explain: `\u300C${p.char}\u300D\u5728\u300C${example}\u300D\u4E2D\u8BFB ${rd.pinyin}${p.meaning ? `\uFF08${p.meaning}\uFF09` : ""}\u3002`
        });
      });
    });
    (lesson.words || []).forEach((w, i) => {
      const { options, answer } = buildOptions(w.meaning, meaningPool, i + 7);
      items.push({
        id: `wd_${lesson.id}_${i}`,
        kind: "wordMeaning",
        category: "word",
        prompt: `\u8BF7\u9009\u51FA\u8BCD\u8BED\u300C${w.word}\u300D\u7684\u6B63\u786E\u91CA\u4E49`,
        options,
        answer,
        explain: `\u300C${w.word}\u300D\u7684\u610F\u601D\u662F\uFF1A${w.meaning}${w.usage ? `\u3000\u7528\u6CD5\uFF1A${w.usage}` : ""}${w.example ? `\u3000\u4F8B\uFF1A${w.example}` : ""}`
      });
    });
    (lesson.fourCharWords || []).forEach((w, i) => {
      const { options, answer } = buildOptions(w.meaning, meaningPool, i + 17);
      items.push({
        id: `fw_${lesson.id}_${i}`,
        kind: "wordMeaning",
        category: "word",
        prompt: `\u8BF7\u9009\u51FA\u8BCD\u8BED\u300C${w.word}\u300D\u7684\u6B63\u786E\u91CA\u4E49`,
        options,
        answer,
        explain: `\u300C${w.word}\u300D\u7684\u610F\u601D\u662F\uFF1A${w.meaning}${w.from ? `\u3000\u51FA\u81EA\uFF1A${w.from}` : ""}`
      });
    });
    return items;
  }
  var GROUP_THRESHOLDS = {
    write: 1,
    recognize: 0.8,
    poly: 0.8,
    word: 0.8
  };
  var GROUP_LABELS = {
    write: "\u4F1A\u5199\u5B57",
    recognize: "\u4F1A\u8BA4\u5B57",
    poly: "\u591A\u97F3\u5B57",
    word: "\u8BCD\u8BED"
  };
  function gradeWordQuiz(quiz, answers, thresholds = GROUP_THRESHOLDS) {
    const gradeGroup = (items, threshold) => {
      const total2 = items.length;
      let correct2 = 0;
      for (const it of items) {
        if (answers && answers[it.id] === it.answer) correct2 += 1;
      }
      const score2 = total2 === 0 ? 1 : correct2 / total2;
      const passed2 = total2 === 0 ? true : threshold >= 1 ? correct2 === total2 : score2 >= threshold;
      return { total: total2, correct: correct2, score: score2, threshold, passed: passed2 };
    };
    const groups = {};
    for (const cat of Object.keys(thresholds)) {
      groups[cat] = gradeGroup(quiz.filter((it) => it.category === cat), thresholds[cat]);
    }
    const passed = Object.keys(groups).every((k) => groups[k].passed);
    const readCats = ["recognize", "poly", "word"].filter((c) => groups[c]);
    const readTotal = readCats.reduce((s, c) => s + groups[c].total, 0);
    const readCorrect = readCats.reduce((s, c) => s + groups[c].correct, 0);
    const readPassed = readCats.every((c) => groups[c].passed);
    const total = quiz.length;
    const correct = Object.keys(groups).reduce((s, k) => s + groups[k].correct, 0);
    const score = total === 0 ? 1 : correct / total;
    return {
      total,
      correct,
      score,
      passed,
      groups,
      write: groups.write,
      read: {
        total: readTotal,
        correct: readCorrect,
        score: readTotal === 0 ? 1 : readCorrect / readTotal,
        passed: readPassed
      }
    };
  }

  // src/data/helpers.js
  var CATEGORIES = ["\u5B57\u8BCD", "\u8BCD\u53E5\u7406\u89E3", "\u60C5\u611F\u8981\u7D20"];
  var DIFFICULTIES = ["basic", "advanced"];
  var ACCUM_STAGES = ["none", "previewed", "studied", "reviewed1", "reviewed2"];
  function qc(id, text, options, correctKey, category, difficulty = "basic", explain2 = "") {
    if (!CATEGORIES.includes(category)) {
      throw new Error(`\u95EE\u9898\u5206\u7C7B\u975E\u6CD5: ${category}\uFF08\u5E94\u4E3A ${CATEGORIES.join("/")}\uFF09`);
    }
    if (!DIFFICULTIES.includes(difficulty)) {
      throw new Error(`\u95EE\u9898\u96BE\u5EA6\u975E\u6CD5: ${difficulty}\uFF08\u5E94\u4E3A ${DIFFICULTIES.join("/")}\uFF09`);
    }
    if (!Array.isArray(options) || options.length < 2) {
      throw new Error(`\u9009\u62E9\u9898\u9009\u9879\u81F3\u5C11\u9700 2 \u4E2A\uFF08${id}\uFF09`);
    }
    const keys = options.map((o) => o.key);
    if (new Set(keys).size !== keys.length) {
      throw new Error(`\u9009\u62E9\u9898\u9009\u9879 key \u91CD\u590D\uFF08${id}\uFF09`);
    }
    if (!keys.includes(correctKey)) {
      throw new Error(`correctKey \u4E0D\u5728\u9009\u9879\u4E2D\uFF08${id}\uFF09`);
    }
    if (!explain2 || explain2.trim().length < 8) {
      throw new Error(`\u9009\u62E9\u9898\u89E3\u6790\u8FC7\u77ED\uFF08\u81F3\u5C11 8 \u5B57\uFF09: ${id}`);
    }
    return { id, text, options, correctKey, category, difficulty, explain: explain2, type: "choice" };
  }

  // src/core/accum.js
  function nextAccumStage(current) {
    const i = ACCUM_STAGES.indexOf(current);
    if (i < 0 || i >= ACCUM_STAGES.length - 1) return current;
    return ACCUM_STAGES[i + 1];
  }

