    "bigIdea": "\u8FD0\u7528\u6293\u5173\u952E\u8BCD\u3001\u5E26\u7740\u95EE\u9898\u8BFB\u7B49\u9605\u8BFB\u7B56\u7565\uFF0C\u80FD\u5728\u8BFB\u61C2\u7684\u524D\u63D0\u4E0B\u63D0\u9AD8\u9605\u8BFB\u901F\u5EA6\u3002",
    "essentialQuestion": "\u6211\u4EEC\u5982\u4F55\u8FD0\u7528\u9605\u8BFB\u7B56\u7565\uFF0C\u5728\u8BFB\u61C2\u7684\u524D\u63D0\u4E0B\u63D0\u9AD8\u9605\u8BFB\u901F\u5EA6\uFF1F",
    "theme": "\u5B66\u4E60\u63D0\u9AD8\u9605\u8BFB\u901F\u5EA6\u7684\u65B9\u6CD5\uFF0C\u517B\u6210\u5E26\u7740\u95EE\u9898\u5FEB\u901F\u9605\u8BFB\u7684\u4E60\u60EF\u3002",
    "element": "\u9605\u8BFB\u8981\u7D20\uFF1A\u5B66\u4E60\u63D0\u9AD8\u9605\u8BFB\u901F\u5EA6\u7684\u65B9\u6CD5\uFF08\u96C6\u4E2D\u6CE8\u610F\u529B\u3001\u4E0D\u56DE\u8BFB\u3001\u6293\u4F4F\u5173\u952E\u8BCD\u53E5\u3001\u5E26\u7740\u95EE\u9898\u8BFB\uFF09\uFF1B\u4E60\u4F5C\u8981\u7D20\uFF1A\u7ED3\u5408\u5177\u4F53\u4E8B\u4F8B\u5199\u51FA\u4EBA\u7269\u7684\u7279\u70B9\u3002",
