            "usage": "\u6307\u52A8\u690D\u7269\u7684\u751F\u80B2\u3001\u7E41\u884D\uFF0C\u5E38\u7528\u4E8E\u8BF4\u660E\u751F\u7269\u7279\u5F81\u3002",
