    deepIdea: '\u8FD9\u4E00\u5355\u5143\u8BB2\u5199\u666F\uFF0C\u53EF\u5B83\u8981\u6559\u4F60\u7684\u4E0D\u662F"\u628A\u98CE\u666F\u5199\u6F02\u4EAE"\u3002\u4F60\u770B\u8FD9\u4E09\u7BC7\u8BFE\u6587\uFF0C\u6CA1\u6709\u4E00\u7BC7\u5728\u5806"\u7F8E\u4E0D\u80DC\u6536""\u5FC3\u65F7\u795E\u6021"\u8FD9\u6837\u7684\u8BCD\u3002\u300A\u7B2C\u4E00\u573A\u96EA\u300B\u5148\u5199\u96EA\u524D\u4E07\u7C41\u4FF1\u5BC2\u2014\u2014\u6811\u62AB\u7C89\u5986\u7389\u780C\u7684\u767D\uFF0C\u8C01\u4E5F\u4E0D\u52A8\uFF0C\u90A3\u662F\u9759\uFF1B\u96EA\u6084\u65E0\u58F0\u606F\u5730\u843D\u3001\u5B69\u5B50\u5806\u96EA\u4EBA\u63B7\u96EA\u7403\uFF0C\u90A3\u662F\u52A8\u3002\u300A\u767D\u9E6D\u300B\u66F4\u5999\uFF0C\u5F00\u5934\u8BF4\u5B83"\u662F\u4E00\u9996\u7CBE\u5DE7\u7684\u8BD7"\uFF0C\u5148\u5199\u5B83\u9759\u6B62\u65F6\u7684\u6837\u5B50\u2014\u2014\u96EA\u767D\u7684\u84D1\u6BDB\u3001\u6D41\u7EBF\u578B\u7684\u7ED3\u6784\u3001\u94C1\u8272\u7684\u957F\u5599\uFF0C\u50CF\u5D4C\u5728\u73BB\u7483\u6846\u91CC\uFF1B\u63A5\u7740\u5199\u5B83"\u7AD9\u7740\u9493\u9C7C""\u4F4E\u98DE"\uFF0C\u7ED3\u5C3E\u518D\u56DE\u6263\u5F00\u5934\uFF0C\u9996\u5C3E\u547C\u5E94\u3002\u6240\u4EE5\u672C\u5355\u5143\u771F\u6B63\u7684\u672C\u4E8B\u662F\uFF1A**\u5148\u770B\u6E05\u8FD9\u5904\u666F\u7269\u6B64\u523B\u662F\u4EC0\u4E48\u6837\u5B50\uFF08\u9759\u6001\u7684\u5E95\u5B50\uFF09\uFF0C\u518D\u76EF\u4F4F\u5B83\u6B63\u5728\u600E\u4E48\u53D8\uFF08\u52A8\u6001\u7684\u90A3\u53E3\u6C14\uFF09\uFF0C\u7136\u540E\u628A\u8FD9\u6BB5\u53D8\u5316\u6309\u987A\u5E8F\u5199\u51FA\u6765**\u3002\u9759\u7ED9\u4F60\u753B\u9762\uFF0C\u52A8\u7ED9\u4F60\u65F6\u95F4\uFF1B\u6CA1\u6709\u52A8\u7684\u666F\u662F\u4E00\u5F20\u7167\u7247\uFF0C\u6CA1\u6709\u9759\u7684\u666F\u662F\u4E00\u7247\u5FD9\u4E71\u3002\u8FD9\u5C31\u662F\u300A\u6211\u6700\u559C\u7231\u7684\u5B63\u8282\u300B\u8981\u4F60\u505A\u7684\u4E8B\u2014\u2014\u6311\u4E00\u4E2A\u5B63\u8282\uFF0C\u628A\u5B83\u5199\u6D3B\u3002',
    // 2. 孩子必须经历的认知过程 — 通关总结
    cognitiveProcess: [
      '\u5206\uFF1A\u8BFB\u4E00\u6BB5\u5199\u666F\u7684\u6587\u5B57\uFF0C\u5148\u5206\u4E00\u5206\uFF1A\u54EA\u4E9B\u53E5\u5B50\u5199\u7684\u662F"\u505C\u5728\u90A3\u513F\u7684\u6837\u5B50"\uFF0C\u54EA\u4E9B\u5199\u7684\u662F"\u6B63\u5728\u53D1\u751F\u7684\u53D8\u5316"\u3002',
      "\u770B\uFF1A\u76EF\u7740\u9759\u6001\u7684\u53E5\u5B50\u95EE\uFF1A\u5B83\u5199\u7684\u662F\u5F62\u72B6\u3001\u989C\u8272\u8FD8\u662F\u59FF\u6001\uFF1F\u505C\u4F4F\u4E0D\u52A8\u7684\u65F6\u5019\uFF0C\u8FD9\u5904\u666F\u7269\u5230\u5E95\u662F\u4EC0\u4E48\u6A21\u6837\uFF1F",
      '\u8FFD\uFF1A\u76EF\u7740\u52A8\u6001\u7684\u53E5\u5B50\u95EE\uFF1A\u5B83\u5728\u600E\u4E48\u53D8\uFF1F\u53D8\u5F97\u5FEB\u8FD8\u662F\u6162\uFF1F"\u6084\u65E0\u58F0\u606F\u5730\u843D"\u548C"\u6B22\u4E50\u7684\u53EB\u558A\u58F0"\u6709\u4EC0\u4E48\u4E0D\u4E00\u6837\uFF1F',
      '\u609F\uFF1A\u78B0\u5230"\u591C\u534A\u949F\u58F0\u5230\u5BA2\u8239"\u8FD9\u79CD\u53E5\u5B50\uFF0C\u53CD\u8FC7\u6765\u95EE\u4E00\u53E5\uFF1A\u5199\u4E86\u58F0\u97F3\uFF0C\u4E3A\u4EC0\u4E48\u53CD\u800C\u663E\u5F97\u66F4\u9759\uFF1F',
      "\u6BD4\uFF1A\u628A\u300A\u7B2C\u4E00\u573A\u96EA\u300B\u7684\u96EA\u524D\u548C\u96EA\u540E\u6446\u5728\u4E00\u8D77\u6BD4\u2014\u2014\u540C\u4E00\u5904\u5730\u65B9\uFF0C\u4E3A\u4EC0\u4E48\u4E24\u6B21\u5199\u51FA\u6765\u5B8C\u5168\u4E0D\u540C\uFF1F",
      "\u6311\uFF1A\u770B\u81EA\u5DF1\u6700\u559C\u7231\u7684\u90A3\u4E2A\u5B63\u8282\uFF0C\u6311\u51FA\u5B83\u6700\u6709\u4EE3\u8868\u6027\u3001\u9759\u52A8\u90FD\u770B\u5F97\u89C1\u7684\u90A3\u4E00\u5E55\uFF08\u5C31\u50CF\u51AC\u5929\u6311\u7B2C\u4E00\u573A\u96EA\uFF09\u3002",
      '\u5199\uFF1A\u6309"\u5148\u662F\u4EC0\u4E48\u6837 \u2192 \u63A5\u7740\u600E\u4E48\u53D8 \u2192 \u6700\u540E\u53D8\u6210\u4EC0\u4E48\u6837"\u7684\u987A\u5E8F\u5199\u4E0B\u6765\uFF0C\u5199\u51FA\u53D8\u5316\uFF0C\u4E0D\u5199\u8BC4\u8BED\u3002'
    ],
