        explain: '\u9009 B\u3002\u9898\u773C\u5728"\u559C\u7231"\u80CC\u540E\u7684"\u753B\u9762"\u2014\u2014\u5199\u7684\u5FC5\u987B\u662F\u6B64\u523B\u6B63\u5728\u53D1\u751F\u7684\u3001\u6709\u9759\u6709\u53D8\u7684\u5B63\u8282\u753B\u9762\u3002A \u90A3\u6837\u5199\u662F\u5217\u6E05\u5355\u3001\u8D34\u8BC4\u8BED\uFF1A\u8BFB\u8005\u77E5\u9053\u56DB\u5B63\u90FD\u6709\u4EC0\u4E48\uFF0C\u5374\u4EC0\u4E48\u4E5F\u6CA1\u770B\u89C1\u3002B \u628A\u4E00\u4E2A\u5B63\u8282\u5207\u6210\u4E86\u51E0\u6B65\uFF1A\u96EA\u843D \u2192 \u98CE\u628A\u96EA\u5439\u8FDB\u5DF7\u5B50 \u2192 \u5B69\u5B50\u5806\u96EA\u4EBA\u63B7\u96EA\u7403\uFF0C\u8BFB\u8005\u8DDF\u7740\u4F60\u4E00\u6B65\u4E00\u6B65\u770B\u4E0B\u6765\uFF0C\u8111\u5B50\u91CC\u5C31\u6709\u753B\u9762\u4E86\u3002\u8FD9\u4E5F\u6B63\u662F\u300A\u7B2C\u4E00\u573A\u96EA\u300B\u7684\u62DB\uFF1A\u5148\u9759\u540E\u52A8\uFF0C\u6309\u987A\u5E8F\u5199\u3002',
        wrongHint: '"\u7F8E\u4E0D\u80DC\u6536"\u662F\u8BC4\u8BED\uFF0C\u4E0D\u662F\u753B\u9762\u3002\u8BFB\u7684\u4EBA\u8981\u7684\u662F"\u770B\u89C1"\uFF0C\u4E0D\u662F"\u88AB\u544A\u8BC9\u90A3\u91CC\u5F88\u7F8E"\u3002',
