  var ORAL_BY_UNIT = {
    u1: u1_default2,
    u3: u3_default2,
    u4: u4_default2,
    u6: u6_default2,
    u8: u8_default2
  };
  function getOral(unitId) {
    return ORAL_BY_UNIT[unitId] || null;
  }

  // src/core/oralPractice.js
  function evaluateOral(answer = "", task4 = {}) {
    const t = String(answer || "").trim();
    const list = Array.isArray(task4.checklist) ? task4.checklist : [];
    const items = list.map((it) => {
      const kws = Array.isArray(it.keywords) ? it.keywords : [];
      const pass = t.length > 0 && kws.some((k) => t.includes(k));
      return { text: it.text || "", pass, example: it.example || "" };
    });
    return {
      len: t.length,
      tooShort: t.length < 15,
      passed: items.filter((i) => i.pass).length,
      total: items.length,
      items
    };
  }
  function buildOralProbes(task4 = {}) {
    const item = {
      id: task4.id || "oral",
      prompt: task4.prompt || task4.title || "\u8FD9\u6B21\u53E3\u8BED\u4EA4\u9645",
      ability: "\u2464",
      probes: task4.probes
    };
    const list = buildProbes(item, 2);
    return list.map((p, i) => {
      const raw = (task4.probes || [])[i] || {};
      return raw.sample ? { ...p, sample: raw.sample } : p;
    });
  }
  function gradeOralProbe(probe, answer = "") {
    return evaluateProbe(probe, answer);
  }
  function oralDone(state2 = {}) {
    const s = state2 || {};
    const hasAnswer = String(s.answer || "").trim().length >= 15;
    const checks = Array.isArray(s.checks) ? s.checks : [];
    const checked = checks.filter(Boolean).length;
    const probes = Array.isArray(s.probeAnswers) ? s.probeAnswers.map((a) => String(a || "").trim()) : [];
    const probed = probes.filter(Boolean).length >= 1;
    return hasAnswer && checked >= 1 && probed;
  }
  function oralSummary(state2 = {}) {
    const s = state2 || {};
    const done = oralDone(s);
    const fb = s.feedback || null;
    return {
      started: String(s.answer || "").trim().length > 0,
      passed: fb ? fb.passed : 0,
      total: fb ? fb.total : 0,
      done
    };
  }

