        modelGuide: '\u5F15\u5BFC\u6846\u67B6\uFF08\u4E94\u5E74\u7EA7\u4E0A\u5B66\u671F\u8981\u6C42\u7EA6 500 \u5B57\uFF09\uFF1A\u2460 \u70B9\u51FA\u8981"\u6F2B\u753B"\u7684\u662F\u54EA\u4F4D\u8001\u5E08\u3001\u6700\u7A81\u51FA\u7684\u7279\u70B9\u662F\u4EC0\u4E48\uFF1B\u2461 \u6293\u4E00\u5904\u6700\u6709\u6F2B\u753B\u611F\u7684\u6807\u5FD7\uFF08\u4E00\u526F\u773C\u955C\u3001\u4E00\u53E5\u53E3\u5934\u7985\u3001\u4E00\u4E2A\u52A8\u4F5C\uFF09\uFF1B\u2462 \u7528\u4E00\u4E24\u4EF6\u771F\u5B9E\u7684\u5C0F\u4E8B\u628A\u7279\u70B9\u6F14\u51FA\u6765\uFF0C\u5199\u6E05"\u8D77\u56E0\u2014\u4ED6\u600E\u4E48\u505A\u2014\u8BF4\u4E86\u4EC0\u4E48\u2014\u7ED3\u679C"\uFF1B\u2463 \u7ED3\u5C3E\u5199\u51FA\u4F60\u5BF9\u8FD9\u4F4D\u8001\u5E08\u7684\u771F\u5B9E\u611F\u53D7\u3002\u53EF\u501F\u9274\u300A\u5C06\u76F8\u548C\u300B\u7528\u4E8B\u4F8B\u5199\u4EBA\u3001\u300A"\u8BFA\u66FC\u5E95\u53F7"\u9047\u96BE\u8BB0\u300B\u7528\u5BF9\u6BD4\u5199\u4EBA\u3001\u300A\u4EC0\u4E48\u6BD4\u730E\u8C79\u7684\u901F\u5EA6\u66F4\u5FEB\u300B\u7528\u6BD4\u8F83\u5938\u5F20\u7A81\u51FA\u7279\u70B9\u3002',
