    title: "\u4E60\u4F5C\uFF1A\u6211\u7684\u5FC3\u7231\u4E4B\u7269",
    // 五年级上学期要求约 500 字（与 exam/u1.js lv-xizuo 要求一致）
    prompt: "\u4E94\u5E74\u7EA7\u4E0A\u5B66\u671F\u8981\u6C42\u5199\u7EA6 500 \u5B57\u3002\u60F3\u60F3\u4F60\u7684\u5FC3\u7231\u4E4B\u7269\u662F\u4EC0\u4E48\uFF1A\u4E00\u53EA\u5C0F\u52A8\u7269\u3001\u4E00\u4EF6\u73A9\u5177\u3001\u4E00\u76C6\u690D\u7269\uFF0C\u8FD8\u662F\u4E00\u5F20\u7167\u7247\u3001\u4E00\u4EFD\u793C\u7269\uFF1F\u5148\u7528\u4E0B\u9762\u7684\u300C\u601D\u8DEF\u751F\u6210\u5668\u300D\u628A\u60F3\u6CD5\u5B9A\u4E0B\u6765\uFF0C\u518D\u7528\u300C\u8BCD\u6C47\u94F6\u884C\u300D\u628A\u53E5\u5B50\u5199\u6F02\u4EAE\uFF0C\u6309\u300C\u586B\u7A7A\u63D0\u7EB2\u300D\u4E00\u6B65\u6B65\u628A\u56DB\u6B65\u6269\u6210 500 \u5B57\u3002\u5199\u51FA\u5B83\u7684\u6837\u5B50\u3001\u6765\u5386\uFF0C\u548C\u4E00\u4EF6\u4E0E\u5B83\u6709\u5173\u7684\u5C0F\u4E8B\uFF0C\u81EA\u7136\u5730\u8868\u8FBE\u4F60\u7684\u559C\u7231\u4E4B\u60C5\u3002",
    // 单元核心写法：借物抒情 / 借物喻理
    coreMethod: "\u501F\u7269\u6292\u60C5\u56DB\u6B65\u6CD5\uFF08\u672C\u5355\u5143\u300A\u6842\u82B1\u96E8\u300B\u300A\u843D\u82B1\u751F\u300B\u300A\u73CD\u73E0\u9E1F\u300B\u90FD\u7528\u4E86\u201C\u501F\u5177\u4F53\u4E8B\u7269\u6292\u53D1\u611F\u60C5\u201D\u7684\u5199\u6CD5\uFF09",
    // ① 课文与作文的关系（放在首位：先懂每篇课文怎么写自己的心爱之物，再学自己怎么写）
    textRelation: {
      intro: "\u672C\u5355\u5143\u4E09\u7BC7\u8BFE\u6587\uFF0C\u5176\u5B9E\u90FD\u85CF\u7740\u4F5C\u8005\u81EA\u5DF1\u7684\u201C\u5FC3\u7231\u4E4B\u7269\u201D\uFF0C\u800C\u4E14\u6BCF\u4E00\u7BC7\u5199\u6CD5\u90FD\u4E0D\u4E00\u6837\u3002\u6211\u4EEC\u5148\u770B\u6E05\u695A\uFF1A\u5B83\u4EEC\u5404\u81EA\u7684\u5FC3\u7231\u4E4B\u7269\u662F\u4EC0\u4E48\u3001\u662F\u600E\u4E48\u628A\u611F\u60C5\u5199\u51FA\u6765\u7684\u2014\u2014\u8FD9\u4E09\u4F4D\uFF0C\u5C31\u662F\u8FD9\u7BC7\u300A\u6211\u7684\u5FC3\u7231\u4E4B\u7269\u300B\u7684\u5199\u4F5C\u8001\u5E08\u3002",
      texts: [
        {
          text: "\u300A\u843D\u82B1\u751F\u300B",
          object: "\u82B1\u751F\uFF08\u81EA\u5BB6\u540E\u56ED\u79CD\u51FA\u6765\u7684\uFF09",
          how: "\u4ECE\u79CD\u82B1\u751F\u3001\u6536\u82B1\u751F\u3001\u5403\u82B1\u751F\uFF0C\u5199\u5230\u4E00\u5BB6\u4EBA\u56F4\u5750\u201C\u8BAE\u82B1\u751F\u201D\uFF1B\u7528\u5BF9\u6BD4\uFF08\u82F9\u679C\u77F3\u69B4\u6843\u5B50\u6302\u5728\u9AD8\u5904 vs \u82B1\u751F\u57CB\u5728\u5730\u91CC\uFF09\u8BB2\u82B1\u751F\u7684\u53EF\u8D35\u3002",
          feeling: "\u501F\u82B1\u751F\u8BF4\u51FA\u4E00\u4E2A\u9053\u7406\uFF1A\u4EBA\u8981\u505A\u6709\u7528\u7684\u4EBA\uFF0C\u4E0D\u8981\u53EA\u8BB2\u4F53\u9762\u800C\u5BF9\u522B\u4EBA\u6CA1\u597D\u5904\u3002",
          borrow: "\u5B66\u5B83\uFF1A\u7528\u201C\u4E00\u5BB6\u4EBA\u804A\u5929\u201D\u81EA\u7136\u5E26\u51FA\u60F3\u6CD5\uFF1B\u7528\u5BF9\u6BD4\u5199\u7279\u70B9\u3002"
        },
        {
          text: "\u300A\u6842\u82B1\u96E8\u300B",
          object: "\u6842\u82B1\uFF08\u6545\u4E61\u9662\u5B50\u91CC\u7684\u6842\u82B1\u6811\uFF09",
          how: "\u56DE\u5FC6\u5C0F\u65F6\u5019\u201C\u6447\u6842\u82B1\u201D\u7684\u5FEB\u4E50\uFF1A\u62B1\u4F4F\u6811\u6447\uFF0C\u6842\u82B1\u50CF\u96E8\u843D\u6EE1\u5168\u8EAB\uFF1B\u518D\u5199\u6842\u82B1\u7CD5\u3001\u6842\u82B1\u8336\uFF1B\u7ED3\u5C3E\u5199\u79BB\u5F00\u5BB6\u4E61\u540E\uFF0C\u6BCD\u4EB2\u8BF4\u201C\u8FD9\u91CC\u7684\u6842\u82B1\u518D\u9999\uFF0C\u4E5F\u6BD4\u4E0D\u4E0A\u5BB6\u4E61\u7684\u201D\u3002",
          feeling: "\u6292\u53D1\u4E86\u5BF9\u6545\u4E61\u3001\u7AE5\u5E74\u548C\u6BCD\u4EB2\u7684\u6DF1\u6DF1\u601D\u5FF5\u3002",
          borrow: "\u5B66\u5B83\uFF1A\u7528\u4E00\u4EF6\u5177\u4F53\u7684\u5C0F\u4E8B\uFF08\u6447\u6842\u82B1\uFF09\u628A\u611F\u60C5\u5199\u51FA\u6765\uFF1B\u7ED3\u5C3E\u7528\u4E00\u53E5\u8BDD\u70B9\u51FA\u601D\u5FF5\u3002"
        },
        {
          text: "\u300A\u73CD\u73E0\u9E1F\u300B",
          object: "\u73CD\u73E0\u9E1F\uFF08\u4E00\u5BF9\u6E10\u6E10\u4EB2\u8FD1\u4EBA\u7684\u5C0F\u9E1F\uFF09",
          how: "\u6309\u65F6\u95F4\u5199\u5C0F\u9E1F\u4ECE\u201C\u6015\u4EBA\u201D\u5230\u201C\u6E10\u6E10\u80C6\u5927\u201D\u3001\u5230\u201C\u5544\u6211\u7684\u7B14\u5C16\u201D\u3001\u5230\u201C\u8DB4\u5728\u6211\u80A9\u5934\u7761\u7740\u201D\u7684\u53D8\u5316\u8FC7\u7A0B\u3002",
          feeling: "\u6292\u53D1\u4E86\u201C\u4FE1\u8D56\uFF0C\u5F80\u5F80\u521B\u9020\u51FA\u7F8E\u597D\u7684\u5883\u754C\u201D\u3002",
          borrow: "\u5B66\u5B83\uFF1A\u7528\u201C\u4ECE\u2026\u2026\u5230\u2026\u2026\u201D\u7684\u53D8\u5316\u8FC7\u7A0B\u5199\u6545\u4E8B\uFF1B\u628A\u5C0F\u52A8\u7269\u5199\u6D3B\uFF0C\u5199\u5B83\u4E00\u6B65\u6B65\u9760\u8FD1\u4F60\u3002"
        }
      ],
      outro: "\u770B\u660E\u767D\u4E86\u5417\uFF1F\u4E09\u7BC7\u8BFE\u6587\u7684\u201C\u7269\u201D\u5404\u4E0D\u76F8\u540C\uFF08\u690D\u7269\u3001\u98DF\u7269\u3001\u5C0F\u52A8\u7269\uFF09\uFF0C\u4F46\u529E\u6CD5\u90FD\u4E00\u6837\uFF1A\u9009\u4E00\u4E2A\u5177\u4F53\u7684\u7269\uFF0C\u501F\u5B83\u5199\u4E00\u4EF6\u5C0F\u4E8B\uFF0C\u611F\u60C5\u5C31\u81EA\u7136\u201C\u957F\u201D\u51FA\u6765\u4E86\u3002\u6211\u4EEC\u5199\u300A\u6211\u7684\u5FC3\u7231\u4E4B\u7269\u300B\u4E5F\u7167\u8FD9\u4E2A\u529E\u6CD5\u6765\u2014\u2014\u4E0B\u9762\u7684\u56DB\u6B65\u6CD5\u5C31\u662F\u811A\u624B\u67B6\u3002"
    },
    // ② 借物抒情四步法（保持原名，测试与渲染均依赖）
    framework: [
      { step: 1, name: "\u70B9\u9898", tip: "\u5F00\u95E8\u89C1\u5C71\uFF0C\u7B2C\u4E00\u53E5\u5C31\u8BF4\u51FA\u201C\u6211\u7684\u5FC3\u7231\u4E4B\u7269\u662F\xD7\xD7\u201D\uFF0C\u4E0D\u7ED5\u5F2F\u5B50\u3002" },
      { step: 2, name: "\u63CF\u5F62 / \u6765\u5386", tip: "\u7EC6\u81F4\u63CF\u5199\u5916\u5F62\u3001\u7279\u70B9\uFF0C\u7528\u8BCD\u6C47\u94F6\u884C\u7684\u201C\u6BD4\u55BB\u53E5\u6A21\u677F\u201D\u8BA9\u753B\u9762\u9C9C\u660E\uFF1B\u518D\u4EA4\u4EE3\u5B83\u662F\u600E\u4E48\u6765\u7684\uFF08\u8C01\u9001\u7684\u3001\u600E\u4E48\u5F97\u5230\u7684\uFF09\u3002" },
      { step: 3, name: "\u6545\u4E8B\u5E26\u60C5", tip: "\u8BB2\u4E00\u4EF6\u4E0E\u5B83\u76F8\u5173\u7684\u5C0F\u6545\u4E8B\uFF08\u4E00\u6B21\u966A\u4F34\u3001\u4E00\u4E2A\u8BEF\u4F1A\u3001\u4E00\u6BB5\u56DE\u5FC6\uFF09\uFF0C\u8BA9\u611F\u60C5\u81EA\u7136\u5730\u201C\u957F\u201D\u51FA\u6765\uFF0C\u800C\u4E0D\u662F\u786C\u8BF4\u201C\u6211\u5F88\u559C\u6B22\u201D\u3002" },
      { step: 4, name: "\u56DE\u6263", tip: "\u7ED3\u5C3E\u56DE\u5230\u201C\u4E3A\u4EC0\u4E48\u5B83\u662F\u6211\u7684\u5FC3\u7231\u4E4B\u7269\u201D\uFF0C\u70B9\u660E\u5B83\u5E26\u7ED9\u4F60\u7684\u611F\u53D7\u6216\u9053\u7406\uFF0C\u9996\u5C3E\u547C\u5E94\u3002" }
    ],
    // ②-b 四步闯关（跟着步骤一步步练：每步只写一两句，语音优先，提交后立即给讲解与修改示范）
    // 字段：step 序号 | name 步骤名 | goal 本步小目标 | chips 可点选插入的词句
