      { q: "\u539F\u6545\u4E8B\u91CC\u5927\u5BB6\u5370\u8C61\u6700\u6DF1\u7684\u662F\u4EC0\u4E48\uFF1F", options: ["\u5154\u5B50\u7761\u5927\u89C9", "\u72FC\u54AC\u65AD\u4E86\u7267\u7F8A\u72AC\u7684\u8116\u5B50", "\u72D0\u72F8\u5927\u6447\u5927\u6446\u8D70\u5728\u8001\u864E\u524D\u9762", "\u6D77\u529B\u5E03\u53D8\u6210\u4E86\u77F3\u5934", "\u6211\u8BF4\u4E0D\u4E0A\u6765\uFF0C\u56DE\u53BB\u518D\u770B\u4E00\u904D"] },
      { q: '\u4F60\u7684\u8F6C\u6298\u662F"\u60F3\u4E0D\u5230"\u8FD8\u662F"\u4E71\u6765"\uFF1F\u600E\u4E48\u5224\u65AD\uFF1F', options: ["\u4EBA\u7269\u813E\u6C14\u6CA1\u53D8\uFF0C\u53EA\u662F\u5883\u9047\u53D8\u4E86\u2014\u2014\u60F3\u4E0D\u5230\u4F46\u5408\u7406", "\u53EA\u8981\u610F\u5916\u5C31\u884C\uFF0C\u4E0D\u5408\u7406\u4E5F\u5F88\u9177", "\u6211\u8BF4\u4E0D\u51C6\uFF0C\u5199\u5B8C\u8BFB\u7ED9\u5BB6\u4EBA\u542C\uFF0C\u770B\u4ED6\u4EEC\u670D\u4E0D\u670D"] },
      { q: "\u6700\u7CBE\u5F69\u7684\u4E00\u5E55\uFF0C\u4F60\u6253\u7B97\u653E\u6162\u5199\u54EA\u4E9B\u4E1C\u897F\uFF1F", options: ["\u52A8\u4F5C\uFF08\u5148\u2026\u2026\u518D\u2026\u2026\uFF09", "\u5BF9\u8BDD\uFF08\u539F\u8BDD\uFF09", "\u5FC3\u60C5\uFF08\u5FC3\u91CC\u600E\u4E48\u60F3\uFF09", "\u73AF\u5883\uFF08\u58F0\u97F3\u3001\u5149\u7EBF\u3001\u6C14\u5473\uFF09", "\u5168\u90FD\u8981"] }
