    coreMethod: '\u4ECB\u7ECD\u4E8B\u7269\u56DB\u6B65\u6CD5\uFF08\u6293\u7279\u70B9 \u2192 \u60F3\u8BFB\u8005\u5361\u5728\u54EA\u513F \u2192 \u6311\u65B9\u6CD5 \u2192 \u6309\u65B9\u9762\u5206\u6BB5\u5199\uFF09\uFF0C\u672C\u5355\u5143\u300A\u592A\u9633\u300B\u300A\u91D1\u5B57\u5854\u300B\u300A\u9CB8\u300B\u300A\u98CE\u5411\u888B\u7684\u5236\u4F5C\u300B\u5206\u522B\u793A\u8303\u4E86"\u7ED9\u6570\u5B57\u3001\u7528\u6570\u5B57\u548C\u6BD4\u8F83\u3001\u5148\u7EA0\u6B63\u3001\u5206\u6B65\u5199"',
