      { step: 2, name: "\u6293\u4E00\u4E2A\u7EC6\u8282", tip: "\u4ECE\u90A3\u4EF6\u4E8B\u91CC\u6311\u4E00\u6837\u770B\u5F97\u89C1\u7684\u4E1C\u897F\uFF1A\u4E00\u4E2A\u52A8\u4F5C\uFF08\u5F2F\u8170\u3001\u8E2E\u811A\u3001\u628A\u624B\u7F29\u56DE\u6765\uFF09\u3001\u4E00\u53CC\u624B\uFF08\u88C2\u53E3\u3001\u8001\u8327\u3001\u51BB\u7EA2\uFF09\u3001\u4E00\u6837\u65E7\u4E1C\u897F\uFF08\u8865\u8FC7\u7684\u4E66\u5305\u3001\u64E6\u5F97\u53D1\u4EAE\u7684\u996D\u76D2\u3001\u9A91\u4E86\u5341\u5E74\u7684\u8F66\uFF09\u3002\u5199\u5B83\u662F\u600E\u4E48\u65E7\u7684\u3001\u600E\u4E48\u52A8\u7684\u3002" },
      { step: 3, name: "\u5199\u5F53\u65F6\u7684\u573A\u666F", tip: '\u628A\u90A3\u4E00\u523B\u6446\u51FA\u6765\uFF1A\u4EC0\u4E48\u5728\u54CD\u3001\u4EC0\u4E48\u5728\u52A8\u3001\u4ED6\uFF08\u5979\uFF09\u8BF4\u4E86\u54EA\u53E5\u8BDD\u3001\u5468\u56F4\u662F\u4EC0\u4E48\u5929\u6C14\u3002\u522B\u5199"\u6211\u5F88\u611F\u52A8"\uFF0C\u5199\u4F60\u8EAB\u4F53\u7684\u53CD\u5E94\u2014\u2014\u9F3B\u5B50\u4E00\u9178\u3001\u5934\u4F4E\u4E0B\u53BB\u4E86\u3001\u6525\u7740\u4E1C\u897F\u8DD1\u4E86\u51FA\u53BB\u3002' },
      { step: 4, name: "\u70B9\u51FA\u53D8\u5316\uFF08\u6700\u540E\u624D\u8BF4\u5FC3\u91CC\u8BDD\uFF09", tip: '\u6700\u540E\u4E00\u6BB5\u624D\u8BF4\u4F60\u60F3\u8BF4\u7684\u8BDD\uFF1A\u90A3\u4E00\u523B\u6211\u5FFD\u7136\u660E\u767D\u4E86\u4EC0\u4E48\uFF0F\u540E\u6765\u6211\u505A\u4E86\u4EC0\u4E48\u3002\u60F3\u8BF4\u7684\u8BDD\u653E\u5728\u7ED3\u5C3E\u624D\u6709\u5206\u91CF\uFF1B\u4E00\u5F00\u5934\u5C31\u558A"\u60A8\u8F9B\u82E6\u4E86"\uFF0C\u540E\u9762\u5C31\u6CA1\u5F97\u8BF4\u4E86\u3002' }
