    // ⑤ 填空式提纲（教材要素：分段表述，写清推荐的理由）
    outlineTemplate: "\u7B2C\u4E00\u6BB5\uFF08\u57FA\u672C\u4FE1\u606F\uFF09\uFF1A\u6211\u8981\u63A8\u8350\u7684\u4E66\u662F\u300A\u3010\u4E66\u540D\u3011\u300B\uFF0C\u4F5C\u8005\u662F\u3010\u4F5C\u8005\u3011\u3002\u5B83\u8BB2\u7684\u662F\u3010\u4E24\u4E09\u53E5\u8BDD\uFF0C\u522B\u5267\u900F\u7ED3\u5C40\u3011\u3002\n\u7B2C\u4E8C\u6BB5\uFF08\u7406\u7531\u4E00\uFF0B\u8BC1\u636E\uFF09\uFF1A\u9996\u5148\uFF0C\u3010\u4EBA\u7269\uFF0F\u60C5\u8282\u597D\u5728\u54EA\u513F\u3011\u3002\u6BD4\u5982\u3010\u54EA\u4E2A\u4EBA\u3001\u54EA\u4EF6\u4E8B\u2014\u2014\u5199\u5177\u4F53\uFF0C\u53EF\u5F15\u4E00\u53E5\u539F\u8BDD\u3011\u3002\n\u7B2C\u4E09\u6BB5\uFF08\u7406\u7531\u4E8C\uFF0B\u8BC1\u636E\uFF09\uFF1A\u5176\u6B21\uFF0C\u3010\u8BED\u8A00\uFF0F\u5199\u6CD5\u597D\u5728\u54EA\u513F\u3011\u3002\u6BD4\u5982\u3010\u4E3E\u4E00\u5904\u4E3A\u4F8B\u3011\u3002\n\u7B2C\u56DB\u6BB5\uFF08\u7406\u7531\u4E09\uFF0B\u8BC1\u636E\uFF09\uFF1A\u6700\u91CD\u8981\u7684\u662F\uFF0C\u5B83\u8BA9\u6211\u3010\u505A\u6210\u4E86\u4EC0\u4E48\uFF0F\u6539\u53D8\u4E86\u4EC0\u4E48\u3011\u3002\u90A3\u6B21\u3010\u4F60\u81EA\u5DF1\u7684\u4E00\u4EF6\u5C0F\u4E8B\u3011\u3002\n\u7B2C\u4E94\u6BB5\uFF08\u9080\u8BF7\uFF09\uFF1A\u5982\u679C\u4F60\u3010\u4EC0\u4E48\u6837\u7684\u4EBA\u3011\uFF0C\u6211\u60F3\u4F60\u4F1A\u559C\u6B22\u5B83\u3002",
