  // src/core/stepPractice.js
  function evaluateStep(step, text = "") {
    const t = String(text || "");
    const len = t.replace(/\s/g, "").length;
    const min = step && step.minLen || 10;
    const target = step && step.paraTarget || min;
    const started = len >= min;
    const ok = len >= target;
    const need = Math.max(0, target - len);
    let hint;
    if (ok) {
      hint = `\u2705 \u8FD9\u4E00\u6BB5\u8FBE\u6807\uFF08${len} \u5B57\uFF0F\u672C\u6BB5\u8981 ${target} \u5B57\uFF09\u2014\u2014\u8FD9\u4E00\u6B65\u5B8C\u6210\u4E86\uFF0C\u5F80\u4E0B\u8D70\u3002`;
    } else if (started) {
      hint = `\u9AA8\u67B6\u6709\u4E86\uFF08${len} \u5B57\uFF09\uFF0C\u4F46\u8FD9\u4E00\u6B65<b>\u8FD8\u6CA1\u5B8C\u6210</b>\uFF1A\u672C\u6BB5\u8981\u5199\u5230 ${target} \u5B57\uFF0C\u8FD8\u5DEE ${need} \u5B57\u3002\u7528\u4E0B\u9762\u300C\u628A\u8FD9\u4E00\u6B65\u5199\u957F\u300D\u52A0\u7EC6\u8282\u3002`;
    } else {
      hint = `\u5148\u628A\u9AA8\u67B6\u5199\u51FA\u6765\uFF1A\u8FD8\u5DEE ${Math.max(1, min - len)} \u5B57\u5230 ${min} \u5B57\uFF08\u73B0\u5728 ${len} \u5B57\uFF09\u3002\u5199\u5B8C\u9AA8\u67B6\u522B\u505C\u2014\u2014\u8FD9\u4E00\u6B65\u8981\u5199\u5230 ${target} \u5B57\u624D\u7B97\u5B8C\u6210\u3002`;
    }
    return { ok, started, len, min, target, need, hint };
  }
  function stepProgress(steps = [], answers = {}, target = 500) {
    const list = Array.isArray(steps) ? steps : [];
    const total = list.length;
    const tgt = Number(target) || 500;
    let done = 0;
    let written = 0;
    for (const s of list) {
      const t = String((answers || {})[s.step] || "").trim();
      if (t) written += 1;
      if (t.replace(/\s/g, "").length >= (s.paraTarget || 0)) done += 1;
    }
    const totalChars = assembleDraft(list, answers).replace(/\s/g, "").length;
    const reached = totalChars >= tgt;
    return {
      done,
      written,
      total,
      allDone: total > 0 && done >= total && reached,
      totalChars,
      target: tgt,
      reached,
      need: Math.max(0, tgt - totalChars)
    };
  }
  function assembleDraft(steps = [], answers = {}) {
    const list = Array.isArray(steps) ? steps : [];
    const parts = [];
    for (const s of list) {
      const t = String((answers || {})[s.step] || "").trim();
      if (t) parts.push(t);
    }
    return parts.join("\n");
  }
  function draftMeter(steps = [], answers = {}, target = 500) {
    const assembled = assembleDraft(steps, answers);
    const total = assembled.replace(/\s/g, "").length;
    const t = Math.max(1, Number(target) || 500);
    const pct = Math.min(100, Math.round(total / t * 100));
    let level = "L1";
    let levelLabel = "\u9AA8\u67B6\uFF08\u56DB\u53E5\u6210\u5F62\uFF09";
    let next = `\u518D\u5199 ${Math.max(1, 150 - total)} \u5B57\uFF0C\u5C31\u591F L2\uFF08\u7EA6 150 \u5B57\uFF09\u5566`;
    if (total >= 500) {
      level = "L4";
      levelLabel = "\u5B8C\u6574\u6210\u6587 \u{1F389}";
      next = "500 \u5B57\u8FBE\u6210\u2014\u2014\u6EE1\u7EA7\uFF01\u53BB\u8003\u70B9\u5173\u8A8A\u5199\u4F60\u7684\u6B63\u5F0F\u4F5C\u6587\u5427";
    } else if (total >= 300) {
      level = "L3";
      levelLabel = "\u4E24\u6BB5\u5145\u5B9E\uFF08\u7EA6 300 \u5B57\uFF09";
      next = `\u518D\u5199 ${500 - total} \u5B57\uFF0C\u5C31\u591F L4\uFF08\u7EA6 500 \u5B57\uFF09\u5566`;
    } else if (total >= 150) {
      level = "L2";
      levelLabel = "\u4E00\u6BB5\u6210\u5F62\uFF08\u7EA6 150 \u5B57\uFF09";
      next = `\u518D\u5199 ${300 - total} \u5B57\uFF0C\u5C31\u591F L3\uFF08\u7EA6 300 \u5B57\uFF09\u5566`;
    }
    return { total, target: t, pct, level, levelLabel, next, maxed: total >= t };
  }
  function hasPlaceholder(text = "") {
    return /_{2,}/.test(String(text || ""));
  }
  function stepGap(step, text = "") {
    const target = step && step.paraTarget || 0;
    const len = String(text || "").replace(/\s/g, "").length;
    return { len, target, short: target > 0 && len < target * 0.6 };
  }
  function extractSubject(text = "") {
    const t = String(text || "");
    const mObj = t.match(/是\s*([^。，！？,.；;\n]{1,14})/);
    const mName = t.match(/(?:——|—|叫)\s*([^\s。，！？,.；;]{1,8})/);
    const clean = (s) => String(s || "").replace(/[的了呢吧呀]$/, "").trim();
    return {
      object: mObj ? clean(mObj[1]) : "",
      name: mName ? clean(mName[1]) : ""
    };
  }
  function checkEcho(step, text = "") {
    const t = String(text || "");
    const checks = step && step.echoChecks || [];
    const missing = [];
    for (const c of checks) {
      let ok = true;
      try {
        ok = new RegExp(c.re).test(t);
      } catch (e) {
        ok = true;
      }
      if (!ok) missing.push(c.hint);
    }
    return { missing, subject: extractSubject(t) };
  }
  function buildEchoSample(step, text = "") {
    const t = String(text || "").trim();
    const subject = extractSubject(t);
    const fill = (tpl2) => String(tpl2 || "").replace(/\(object\)/g, subject.object || "______").replace(/\(name\)/g, subject.name || "______");
    let tpl = step && step.echoSample && step.echoSample.better || "";
    let ex = step && step.echoSample && step.echoSample.example || "";
    const hay = t + " " + (subject.object || "");
    const list = step && step.echoSample && step.echoSample.templates || [];
    for (const tp of list) {
      if (!tp || !tp.re || !tp.tpl) continue;
      let ok = false;
      try {
        ok = new RegExp(tp.re).test(hay);
      } catch (e) {
        ok = false;
      }
      if (ok) {
        tpl = tp.tpl;
        ex = tp.ex || ex;
        break;
      }
    }
    const why = step && step.echoSample && step.echoSample.why || "";
    return { plain: t, better: fill(tpl), example: fill(ex), why, subject };
  }

