      const qHtml = u.questions.length ? `<div class="pf-block"><div class="pf-label">\u2753 \u597D\u95EE\u9898\uFF08${u.questions.length} \u4E2A\uFF09</div>${u.questions.map((q) => `<div class="pf-q"><span class="pf-level pf-${q.level}">${q.level === "great" ? "\u597D\u95EE\u9898" : "\u4E0D\u9519\u7684\u95EE\u9898"}</span> ${esc(q.q)}</div>`).join("")}</div>` : "";
