    const itemsHtml = (lv.items || []).map((it, ii) => renderExamItem(lv, it, ii, glv, li, confMap)).join("") || (lv.kind === "writing" ? renderWritingBlock(lv, glv, li, unitId, revision, draftText) : "");
    const weakBadge = status === "wrong" ? `<span class="badge red">\u6709\u9519\u9898</span>` : status === "mastered" ? `<span class="badge green">\u5DF2\u638C\u63E1</span>` : "";
