    const rubric = (lv.rubric || []).map((r) => `<li>${esc(r)}</li>`).join("");
    const revHtml = g ? renderRevisionBox(lv, revision && revision.v1 || g.userAnswer || "", revision && revision.v2 || "", unitId) : "";
    const target = writingTargetOf(lv);
    const tipSuffix = lv.focusHint ? `\uFF08${esc(lv.focusHint)}\uFF09` : target < DEFAULT_WRITING_TARGET ? "\uFF08\u7F29\u5199\u662F\u5199\u77ED\uFF0C\u4E0D\u662F\u5199\u957F\u2014\u2014\u522B\u4E3A\u4E86\u51D1\u5B57\u6570\u628A\u63CF\u5199\u52A0\u56DE\u53BB\uFF01\uFF09" : "";
